std::span<const StoryTrope> story_tropes() { return kTropes; }

const StoryTrope* story_trope(std::string_view id) {
    for (const StoryTrope& trope : kTropes) {
        if (trope.id == id) return &trope;
    }
    return nullptr;
}

const StoryWeightPolicy& story_weight_policy() { return kWeights; }
std::span<const std::string_view> story_gainable_features() { return kGainable; }

const StoryConstraint& story_constraints_for(std::string_view archetype) {
    if (!archetype.empty()) {
        for (const StoryConstraint& row : kConstraints) {
            if (row.archetype == archetype) return row;
        }
    }
    return kConstraints[0];
}

std::span<const std::string_view> story_hero_features() { return kHeroFeatures; }
std::span<const std::string_view> story_world_facts() { return kWorldFacts; }
std::span<const std::string_view> story_facts() { return kFacts; }
std::span<const std::string_view> story_claim_verbs() { return kClaimVerbs; }
std::span<const std::string_view> story_bond_kinds() { return kBondKinds; }
std::span<const std::string_view> story_tiers() { return kTiers; }
std::span<const std::string_view> story_situations() { return kSituations; }
std::span<const std::string_view> story_never_computed() { return kNeverComputed; }
std::span<const StoryFallback> story_bind_fallbacks() { return kFallbacks; }

bool story_known_fact(std::string_view token) {
    if (std::binary_search(std::begin(kFacts), std::end(kFacts), token)) return true;
    constexpr std::string_view kPrefix = "archetype:";
    return token.size() > kPrefix.size() && token.substr(0, kPrefix.size()) == kPrefix;
}

int story_thread_rank(std::string_view kind) {
    for (const RankRow& row : kThreadRank) {
        if (row.kind == kind) return row.rank;
    }
    return -1;
}

StoryCatalogueIdentity story_catalogue_identity() {
    return {1, 7, 1, 3, "aed795b2ce0aaa8ffb84be576bb9102ae4197b896df69d41c9fa804a97652856"};
}

std::string_view story_web_method() { return kMethod; }
std::string_view story_web_limits() { return kLimits; }

